Commentary:

1. Maher Azzouzi working with Trend Micro Zero Day Initiative was reported as
the person who found the issue. I requested to get a proper email to add to the
reported-by tag but got no response. For this reason i will credit the person
i exchanged emails with i.e zdi-disclosures@trendmicro.com

2. Neither i nor Victor who did a much more thorough testing was able to
reproduce a UAF with the PoC or other approaches we tried. We were both able to
reproduce a null ptr deref. After exchange with zdi-disclosures@trendmicro.com
they sent a small change to be made to the code to add an extra delay which
was able to simulate the UAF. i.e, this:
   qdisc_put(q->classes[i].qdisc);
   mdelay(90);
   q->classes[i].qdisc = NULL;

I was informed by Thomas Gleixner(tglx@linutronix.de) that adding delays was
acceptable approach for demonstrating the bug, quote:
"Adding such delays is common exploit validation practice"
The equivalent delay could happen "by virt scheduling the vCPU out, SMIs,
NMIs, PREEMPT_RT enabled kernel"

3. I asked the OP to test and report back but got no response and after a
few days gave up and proceeded to submit this fix.

Fixes: de6d25924c2a ("net/sched: sch_ets: don't peek at classes beyond 'nbands'")
Reported-by: zdi-disclosures@trendmicro.com
Tested-by: Victor Nogueira <victor@mojatatu.com>
Signed-off-by: Jamal Hadi Salim <jhs@mojatatu.com>
Reviewed-by: Davide Caratti <dcaratti@redhat.com>
Link: https://patch.msgid.link/20251128151919.576920-1-jhs@mojatatu.com
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
Race condition in ets_qdisc_change where classes being removed due to band count reduction are not always removed from the active list before their qdiscs are freed, allowing concurrent ets_qdisc_dequeue to access freed memory and cause use-after-free.

Here is the patch:

 static int ets_qdisc_change(struct Qdisc *sch, struct nlattr *opt,
 			    struct netlink_ext_ack *extack)
 {
 	unsigned int quanta[TCQ_ETS_MAX_BANDS] = {0};
 	struct Qdisc *queues[TCQ_ETS_MAX_BANDS];
 	struct ets_sched *q = qdisc_priv(sch);
 	struct nlattr *tb[TCA_ETS_MAX + 1];
 	unsigned int oldbands = q->nbands;
 	u8 priomap[TC_PRIO_MAX + 1];
 	unsigned int nstrict = 0;
 	unsigned int nbands;
 	unsigned int i;
 	int err;

 	err = nla_parse_nested(tb, TCA_ETS_MAX, opt, ets_policy, extack);
 	if (err < 0)
 		return err;

 	if (!tb[TCA_ETS_NBANDS]) {
 		NL_SET_ERR_MSG_MOD(extack, "Number of bands is a required argument");
 		return -EINVAL;
 	}
 	nbands = nla_get_u8(tb[TCA_ETS_NBANDS]);
 	if (nbands < 1 || nbands > TCQ_ETS_MAX_BANDS) {
 		NL_SET_ERR_MSG_MOD(extack, "Invalid number of bands");
 		return -EINVAL;
 	}
 	/* Unless overridden, traffic goes to the last band. */
 	memset(priomap, nbands - 1, sizeof(priomap));

 	if (tb[TCA_ETS_NSTRICT]) {
 		nstrict = nla_get_u8(tb[TCA_ETS_NSTRICT]);
 		if (nstrict > nbands) {
 			NL_SET_ERR_MSG_MOD(extack, "Invalid number of strict bands");
 			return -EINVAL;
 		}
 	}

 	if (tb[TCA_ETS_PRIOMAP]) {
 		err = ets_qdisc_priomap_parse(tb[TCA_ETS_PRIOMAP],
 					      nbands, priomap, extack);
 		if (err)
 			return err;
 	}

 	if (tb[TCA_ETS_QUANTA]) {
 		err = ets_qdisc_quanta_parse(sch, tb[TCA_ETS_QUANTA],
 					     nbands, nstrict, quanta, extack);
 		if (err)
 			return err;
 	}
 	/* If there are more bands than strict + quanta provided, the remaining
 	 * ones are ETS with quantum of MTU. Initialize the missing values here.
 	 */
 	for (i = nstrict; i < nbands; i++) {
 		if (!quanta[i])
 			quanta[i] = psched_mtu(qdisc_dev(sch));
 	}

 	/* Before commit, make sure we can allocate all new qdiscs */
 	for (i = oldbands; i < nbands; i++) {
 		queues[i] = qdisc_create_dflt(sch->dev_queue, &pfifo_qdisc_ops,
 					      ets_class_id(sch, &q->classes[i]),
 					      extack);
 		if (!queues[i]) {
 			while (i > oldbands)
 				qdisc_put(queues[--i]);
 			return -ENOMEM;
 		}
 	}

 	sch_tree_lock(sch);

 	for (i = nbands; i < oldbands; i++) {
-		if (i >= q->nstrict && q->classes[i].qdisc->q.qlen)
+		if (cl_is_active(&q->classes[i]))
 			list_del_init(&q->classes[i].alist);
 		qdisc_purge_queue(q->classes[i].qdisc);
 	}

 	WRITE_ONCE(q->nbands, nbands);
 	for (i = nstrict; i < q->nstrict; i++) {
 		if (q->classes[i].qdisc->q.qlen) {
 			list_add_tail(&q->classes[i].alist, &q->active);
 			q->classes[i].deficit = quanta[i];
 		}
 	}
 	WRITE_ONCE(q->nstrict, nstrict);
 	memcpy(q->prio2band, priomap, sizeof(priomap));

 	for (i = 0; i < q->nbands; i++)
 		WRITE_ONCE(q->classes[i].quantum, quanta[i]);

 	for (i = oldbands; i < q->nbands; i++) {
 		q->classes[i].qdisc = queues[i];
 		if (q->classes[i].qdisc != &noop_qdisc)
 			qdisc_hash_add(q->classes[i].qdisc, true);
 	}

 	sch_tree_unlock(sch);

 	ets_offload_change(sch);
 	for (i = q->nbands; i < oldbands; i++) {
 		qdisc_put(q->classes[i].qdisc);
 		q->classes[i].qdisc = NULL;
 		WRITE_ONCE(q->classes[i].quantum, 0);
 		q->classes[i].deficit = 0;
 		gnet_stats_basic_sync_init(&q->classes[i].bstats);
 		memset(&q->classes[i].qstats, 0, sizeof(q->classes[i].qstats));
 	}
 	return 0;
 }



